  layout(set = 1, binding = 3) uniform sampler2D add_texture;
  layout(set = 1, binding = 2) uniform Constant{
    vec4 add_color;
    vec2 add_offset;
    vec2 add_scale;
    float add_rotate;
  };
#endif
  layout(set = 2, binding = 12) uniform sampler2D cc_spriteTexture;
  vec4 frag () {
      vec2 uv = uv0;
      #if USE_UV1
        uv = uv1;
      #endif
      vec4 o = CCSampleWithAlphaSeparated(cc_spriteTexture, fract(uv0 + vec2(-main_offset.x, main_offset.y)));
      ALPHA_TEST(o);
      float y_flip = 1.0;
      #if OFFSET_Y_FLIP
          y_flip = -1.0;
      #endif
